from __future__ import absolute_import
import logging
from taf.ul.oam.selenium_rap_manager.common import LocalBasicPage


class Logout(LocalBasicPage):

    def __init__(self, driver):
        super(Logout, self).__init__(driver)

    def logout_and_exit_browser(self):
        self.logout()
        self._driver.quit()
        logging.info("logout and exit browser sucessfully")
